using System;using System.IO;using System.Diagnostics;using System.Threading;using AutoCat.Diagnostics;
class LiveTest {
 static string folder,dll;static StreamWriter report;
 static void Main(string[] args){folder=args[0];dll=args[1];Directory.CreateDirectory(folder);using(report=new StreamWriter(Path.Combine(folder,"live-results.txt"))){try{if(Process.GetProcessesByName("autocat").Length!=0)throw new Exception("Unload autocat before test");var games=Process.GetProcessesByName("BongoCat");if(games.Length!=1)throw new Exception("Expected one Bongo Cat");int pid=games[0].Id;foreach(var level in new[]{LogLevel.Error,LogLevel.Info,LogLevel.Debug,LogLevel.Trace})Phase(pid,level);Write("PASS phase sequence completed without game restart");}catch(Exception e){Write("FAIL "+e);Environment.ExitCode=1;}finally{if(Diag.Current!=null){Diag.Current.Dispose();Diag.Current.WaitForDrain(3000);Diag.Current=null;}}}}
 static void Write(string message){report.WriteLine(DateTime.UtcNow.ToString("o")+" "+message);report.Flush();}
 static void Phase(int pid,LogLevel level){Diag.Session=Guid.NewGuid().ToString("N");Diag.Level=level;Diag.Current=new DiagnosticLog("menu");Diag.Current.Configure(Path.Combine(Path.GetDirectoryName(dll),"autocat-data/logs"),Diag.Session,level);Diag.Write(LogLevel.Info,"Session","test.start","Isolated live diagnostics test; runtime 100; no account/storage writes by logger");Write("START level="+level+" session="+Diag.Session);
  using(var taps=new TapEngine())using(var bridge=new BridgeClient(dll,taps)){taps.Start();bridge.Start();var wait=Stopwatch.StartNew();while(!bridge.State.Ready&&wait.ElapsedMilliseconds<15000)Thread.Sleep(100);if(!bridge.State.Ready)throw new Exception("Attach failed: "+bridge.Connection);Write("ATTACHED pid="+pid+" lifetime="+bridge.State.Lifetime);Measure("idle",pid,bridge,taps,15);
   bridge.UnlockAll=true;bridge.Emoting=true;bridge.EmoteRate=200;bridge.Running=true;taps.Rate=200;taps.Enabled=true;Measure("combined_unlock",pid,bridge,taps,25);taps.Enabled=false;bridge.Running=false;bridge.Emoting=false;bridge.UnlockAll=false;Thread.Sleep(2500);Write("RESTORED level="+level+" message="+bridge.State.Message+" lifetime="+bridge.State.Lifetime);Diag.Write(LogLevel.Info,"Session","test.stop","Observed phase complete; unload requested");}
  Thread.Sleep(2500);Diag.Current.Dispose();Diag.Current.WaitForDrain(3000);Write("LOGGER failures="+Diag.Current.Failures+" peakQueue="+Diag.Current.PeakQueued);Diag.Current=null;
 }
 static void Measure(string mode,int pid,BridgeClient bridge,TapEngine taps,int seconds){using(var game=Process.GetProcessById(pid))using(var host=Process.GetCurrentProcess()){game.Refresh();host.Refresh();double gCpu=game.TotalProcessorTime.TotalMilliseconds,hCpu=host.TotalProcessorTime.TotalMilliseconds;long gMem=game.PrivateMemorySize64,hMem=host.PrivateMemorySize64,sent=taps.Sent;int lifetime=bridge.State.Lifetime,emotes=bridge.State.EmoteTotal;double sum=0,max=0;int samples=0;var watch=Stopwatch.StartNew();for(int i=0;i<seconds;i++){Thread.Sleep(1000);if(!bridge.State.Ready)throw new Exception("State unavailable: "+bridge.State.Message);if(i>=5){sum+=bridge.State.FrameMs;max=Math.Max(max,bridge.State.PeakMs);samples++;}}game.Refresh();host.Refresh();Write(mode+" wallMs="+watch.ElapsedMilliseconds+" gameCpuMs="+(game.TotalProcessorTime.TotalMilliseconds-gCpu)+" hostCpuMs="+(host.TotalProcessorTime.TotalMilliseconds-hCpu)+" gamePrivateDelta="+(game.PrivateMemorySize64-gMem)+" hostPrivateDelta="+(host.PrivateMemorySize64-hMem)+" frameAvgMs="+(sum/Math.Max(1,samples)).ToString("F3")+" maxWindowPeakMs="+max.ToString("F3")+" sentDelta="+(taps.Sent-sent)+" lifetimeDelta="+(bridge.State.Lifetime-lifetime)+" emoteDelta="+(bridge.State.EmoteTotal-emotes)+" message="+bridge.State.Message);}}
}
